import React, { useEffect, useRef, useState } from "react";
import { Link, useLocation } from "react-router-dom";

import Home from "@mui/icons-material/Home";
import QueryStatsIcon from "@mui/icons-material/QueryStats";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import RestoreIcon from "@mui/icons-material/Restore";
import AddCardIcon from '@mui/icons-material/AddCard';
import { useTranslation } from "react-i18next";
import "./NavBottom.css";
import Nameweb from "../../../Function/Nameweb";
import Logoweb from "../../../Function/Logoweb";


const NavigationMenu = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const menuRef = useRef(null);
  const menuBorderRef = useRef(null);
  const activeItemRef = useRef(null);
  const [isAnimating, setIsAnimating] = useState(false);

  const offsetMenuBorder = (element, menuBorder) => {
    if (!element || !menuBorder || !menuRef.current || isAnimating) return;

    const offsetActiveItem = element.getBoundingClientRect();
    const left = Math.floor(
      offsetActiveItem.left -
        menuRef.current.offsetLeft -
        (menuBorder.offsetWidth - offsetActiveItem.width) / 2
    );

    setIsAnimating(true);

    // Get the actual current position from the transform
    const currentTransform = window.getComputedStyle(menuBorder).transform;
    let currentPosition = 0;

    if (currentTransform && currentTransform !== "none") {
      // Extract the x translation value from the matrix
      const matrix = new DOMMatrix(currentTransform);
      currentPosition = matrix.m41; // Get the X translation value
    }

    // Set the animation properties
    menuBorder.style.setProperty("--prev-position", `${currentPosition}px`);
    menuBorder.style.setProperty("--new-position", `${left}px`);

    // Remove existing animation classes
    menuBorder.classList.remove("slide-left", "slide-right");
    void menuBorder.offsetWidth; // Force reflow

    // Add appropriate animation class
    menuBorder.classList.add(
      left > currentPosition ? "slide-right" : "slide-left"
    );

    // Update the transform
    menuBorder.style.transform = `translate3d(${left}px, 0, 0)`;

    // Reset animation state after completion
    setTimeout(() => {
      setIsAnimating(false);
    }, 100);
  };

  const handleResize = () => {
    if (!menuRef.current || isAnimating) return;

    if (activeItemRef.current && menuBorderRef.current) {
      requestAnimationFrame(() => {
        offsetMenuBorder(activeItemRef.current, menuBorderRef.current);
      });
    }
  };

  useEffect(() => {
    const debouncedResize = debounce(handleResize, 150);
    window.addEventListener("resize", debouncedResize);
    return () => window.removeEventListener("resize", debouncedResize);
  }, []);

  function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
      const later = () => {
        clearTimeout(timeout);
        func(...args);
      };
      clearTimeout(timeout);
      timeout = setTimeout(later, wait);
    };
  }

  useEffect(() => {
    if (isAnimating) return;

    const currentPath = location.pathname;
    const activeElement = document.querySelector(".menucus__item.active");

    if (activeElement?.id === getElementIdFromPath(currentPath)) return;

    if (activeElement) {
      activeElement.classList.remove("active");
    }

    const newActiveElement = document.getElementById(
      getElementIdFromPath(currentPath)
    );

    if (newActiveElement) {
      newActiveElement.classList.add("active");
      activeItemRef.current = newActiveElement;
      if (menuBorderRef.current) {
        requestAnimationFrame(() => {
          offsetMenuBorder(newActiveElement, menuBorderRef.current);
        });
      }
    }
  }, [location, isAnimating]);

  const getElementIdFromPath = (path) => {
    switch (path) {
      case "/login/":
        return "urlcheck_home";
      case "/login/trade":
        return "urlcheck_trade";
      case "/login/trade_history":
        return "urlcheck_trade_history";
      case "/login/account":

      case "/login/edit_profile":
      case "/login/verify":
      case "/login/withdraw":
      case "/login/transaction_history":
      case "/login/aboutus":
        return "urlcheck_account";
        case"/login/deposit":
        return "urlcheck_deposit";
      default:
        return null;
    }
  };

  return (
    <>
      <div className="menucus" ref={menuRef}>
                <Link className="menucus__item" id="urlcheck_home" to="/login/">
          <div className="icon">
          {/* <Logoweb
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            /> */}
            <Home
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />
            <p className="spanmenucus ">{t("home")}</p>
          </div>
        </Link>
                <Link className="menucus__item" id="urlcheck_trade" to="/login/trade">
          <div className="icon">
            <QueryStatsIcon
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />
            <p className="spanmenucus">{t("trade")}</p>
          </div>
        </Link>
                <Link
          className="menucus__item"
          id="urlcheck_trade_history"
          to="/login/trade_history"
        >
          <div className="icon">
            <RestoreIcon
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />
            <p className="spanmenucus">{t("trade_history")}</p>
          </div>
        </Link>
      <Link className="menucus__item" id="urlcheck_deposit" to="/login/deposit">
          <div className="icon">
            <AddCardIcon
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />
            <p className="spanmenucus">{t("deposit")}</p>
          </div>
        </Link>
        {/* <Link className="menucus__item" id="urlcheck_home" to="/login/">
          <div className="icon">
            <Home
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />
            <p className="spanmenucus">{t("home")}</p>
          </div>
        </Link> */}


        {/* <div className="menucus__item">
          <div className="icon">
            <Logoweb
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />

          </div>
        </div> */}




        <Link
          className="menucus__item"
          id="urlcheck_account"
          to="/login/account"
        >
          <div className="icon">
            <AccountCircleIcon
              style={{ filter: "drop-shadow(1px 1px 2px black)" }}
              className="imgmenucus"
            />
            <p className="spanmenucus">{t("info")}</p>
          </div>
        </Link>

        <div className="menucus__border" ref={menuBorderRef}></div>
      </div>

      <div className="svg-container">
        <svg viewBox="0 0 202.9 45.5">
          <clipPath
            id="menucus"
            clipPathUnits="objectBoundingBox"
            transform="scale(0.0049285362247413 0.021978021978022)"
          >
            <path
              d="M6.7,45.5c5.7,0.1,14.1-0.4,23.3-4c5.7-2.3,9.9-5,18.1-10.5c10.7-7.1,11.8-9.2,20.6-14.3c5-2.9,9.2-5.2,15.2-7
              c7.1-2.1,13.3-2.3,17.6-2.1c4.2-0.2,10.5,0.1,17.6,2.1c6.1,1.8,10.2,4.1,15.2,7c8.8,5,9.9,7.1,20.6,14.3c8.3,5.5,12.4,8.2,18.1,10.5
              c9.2,3.6,17.6,4.2,23.3,4H6.7z"
            />
          </clipPath>
        </svg>
      </div>
    </>
  );
};

export default NavigationMenu;
