import React, { useState, useEffect } from "react";
import "./style.css";
import { useNavigate } from "react-router-dom";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";

import CryptoCarousel from "./Mainsite/CryptoCarousel";

import MenuIcon from "@mui/icons-material/Menu";
import CloseIcon from "@mui/icons-material/Close";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import ArrowOutwardIcon from "@mui/icons-material/ArrowOutward";
import AddIcon from "@mui/icons-material/Add";
import CheckIcon from "@mui/icons-material/Check";

import CurrencyExchangeIcon from "@mui/icons-material/CurrencyExchange";
import CandlestickChartIcon from "@mui/icons-material/CandlestickChart";
import ShowChartIcon from "@mui/icons-material/ShowChart";
import DiamondIcon from "@mui/icons-material/Diamond";
import OilBarrelIcon from "@mui/icons-material/OilBarrel";
import BusinessCenterIcon from "@mui/icons-material/BusinessCenter";

import BoltIcon from "@mui/icons-material/Bolt";
import SpeedIcon from "@mui/icons-material/Speed";
import SecurityIcon from "@mui/icons-material/Security";
import PhoneIphoneIcon from "@mui/icons-material/PhoneIphone";
import SupportAgentIcon from "@mui/icons-material/SupportAgent";
import SchoolIcon from "@mui/icons-material/School";

import GroupsIcon from "@mui/icons-material/Groups";
import AccountBalanceWalletIcon from "@mui/icons-material/AccountBalanceWallet";
import QueryStatsIcon from "@mui/icons-material/QueryStats";

import { LazyLoadImage } from "react-lazy-load-image-component";
import phone_trade from "../../image/notebook_trade.webp";
import trade_desktop from "../../image/trade_com.webp";

import Logoweb from "../../Function/Logoweb";
import Nameweb from "../../Function/Nameweb";
import API_URL from "../../config/api";
import { TOKEN_KEY } from "../../config/token_key";
import LanguageSelector from "../language-selector";
import ChatwootComponent2 from "./ChatwootWidget2";

export default function MainWebsite() {
  const { t } = useTranslation();
  const navigate = useNavigate();

  const [webname, setWebname] = useState("");
  const [websiteURL, setWebsiteURL] = useState("");
  const [gmailURL, setGmailURL] = useState("");

  const [userId] = useState(localStorage.getItem(`${TOKEN_KEY}Id`));

  const isMobile = window.innerWidth <= 768 ? true : false;
  const [isOpen, setIsOpen] = useState(false);
  const [isready, setIsready] = useState(true);
  const [menuOpen, setMenuOpen] = useState(false);
  const [openFaq, setOpenFaq] = useState(-1);

  const handleToggle = () => {
    const newState = !isOpen;
    window.$chatwoot.toggle(newState ? "open" : "close");
    setIsOpen(newState);
  };

  useEffect(() => {
    const handleChatwootReady = async () => {
      setIsready(false);
    };
    window.addEventListener("chatwoot:ready", handleChatwootReady);
    return () => {
      window.removeEventListener("chatwoot:ready", handleChatwootReady);
    };
  }, []);

  useEffect(() => {
    getWebUrl();
    getWebUrlName();
  }, []);

  const getWebUrlName = async () => {
    await API_URL.get(`api/weburl/getlogoandname`)
      .then((res) => {
        const allweburl = res.data;
        if (allweburl.length !== 0) {
          const reswebname = allweburl.find(({ name }) => name === "webname");
          setWebname(reswebname.nameurl);
        } else {
          setWebname("");
        }
        return res.data;
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const getWebUrl = async () => {
    await API_URL.get(`api/weburl/getallweburl`)
      .then((res) => {
        const allweburl = res.data;
        if (allweburl.length !== 0) {
          const resWebsite = allweburl.find(({ name }) => name === "website");
          setWebsiteURL(resWebsite.nameurl);
          const resGmail = allweburl.find(({ name }) => name === "gmail");
          setGmailURL(resGmail.nameurl);
        }
        return res.data;
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const toLogin = () => {
    setMenuOpen(false);
    if (!userId) {
      navigate("/login/2");
    } else {
      navigate("/login/");
    }
  };

  const toRegister = () => {
    setMenuOpen(false);
    if (!userId) {
      navigate("/login/1");
    } else {
      navigate("/login/");
    }
  };

  const openChat = () => {
    setMenuOpen(false);
    if (window.$chatwoot) window.$chatwoot.toggle("open");
  };

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  /* ─────────────────────────  CONTENT  ───────────────────────── */

  const navLinks = [
    { id: "markets", label: t("mw_nav_markets") },
    { id: "why", label: t("mw_nav_why") },
    { id: "platform", label: t("mw_nav_platform") },
    { id: "start", label: t("mw_nav_start") },
  ];

  const stats = [
    { val: "0.0", unit: "pips", label: t("mw_stat_spread") },
    { val: "30", unit: "ms", label: t("mw_stat_execution") },
    { val: "1M+", unit: "", label: t("mw_stat_traders") },
    { val: "$5B+", unit: "", label: t("mw_stat_volume") },
  ];

  const markets = [
    {
      icon: CurrencyExchangeIcon,
      name: t("mw_market_fx"),
      txt: t("mw_market_fx_txt"),
      count: "60+",
    },
    {
      icon: CandlestickChartIcon,
      name: t("mw_market_crypto"),
      txt: t("mw_market_crypto_txt"),
      count: "40+",
    },
    {
      icon: ShowChartIcon,
      name: t("mw_market_indices"),
      txt: t("mw_market_indices_txt"),
      count: "20+",
    },
    {
      icon: DiamondIcon,
      name: t("mw_market_metals"),
      txt: t("mw_market_metals_txt"),
      count: "10+",
    },
    {
      icon: OilBarrelIcon,
      name: t("mw_market_energy"),
      txt: t("mw_market_energy_txt"),
      count: "8+",
    },
    {
      icon: BusinessCenterIcon,
      name: t("mw_market_shares"),
      txt: t("mw_market_shares_txt"),
      count: "100+",
    },
  ];

  // เหรียญ/สินทรัพย์ที่โชว์เป็นชิปเล็ก ๆ ใต้ปุ่มใน hero (ไฟล์อยู่ใน public/)
  const assetChips = [
    { src: "/btc_icon.webp", alt: "BTC" },
    { src: "/eth_icon.webp", alt: "ETH" },
    { src: "/bnb_icon.webp", alt: "BNB" },
    { src: "/xau_icon.webp", alt: "XAU" },
  ];

  const reasons = [
    { icon: BoltIcon, head: t("mw_why1"), txt: t("mw_why1_txt") },
    { icon: SpeedIcon, head: t("mw_why2"), txt: t("mw_why2_txt") },
    { icon: SecurityIcon, head: t("mw_why3"), txt: t("mw_why3_txt") },
    { icon: PhoneIphoneIcon, head: t("mw_why4"), txt: t("mw_why4_txt") },
    { icon: SupportAgentIcon, head: t("mw_why5"), txt: t("mw_why5_txt") },
    { icon: SchoolIcon, head: t("mw_why6"), txt: t("mw_why6_txt") },
  ];

  const platformPoints = [
    t("tradingbenefitslist1"),
    t("tradingbenefitslist2"),
    t("tradingbenefitslist3"),
    t("tradingbenefitslist4"),
    t("tradingbenefitslist5"),
  ];

  const steps = [
    { icon: GroupsIcon, head: t("ST3S_head1"), txt: t("ST3S_txt1") },
    {
      icon: AccountBalanceWalletIcon,
      head: t("ST3S_head2"),
      txt: t("ST3S_txt2"),
    },
    { icon: QueryStatsIcon, head: t("ST3S_head3"), txt: t("ST3S_txt3") },
  ];

  const assurances = [t("mw_trust1"), t("mw_trust2"), t("mw_trust3")];

  const faqs = [
    { q: t("mw_faq_q1"), a: t("mw_faq_a1") },
    { q: t("mw_faq_q2"), a: t("mw_faq_a2") },
    { q: t("mw_faq_q3"), a: t("mw_faq_a3") },
    { q: t("mw_faq_q4"), a: t("mw_faq_a4") },
  ];

  const num = (i) => String(i + 1).padStart(2, "0");

  /* ─────────────────────────  RENDER  ───────────────────────── */

  return (
    <div className="w-full min-h-screen bg-[#060309] text-white antialiased">
      {/* ── NAV ── */}
      <header className="sticky top-0 z-50 border-b border-white/10 bg-[#060309]/85 backdrop-blur-xl">
        <nav className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-4 px-5 sm:px-8">
          <Link to="/" className="flex flex-shrink-0 items-center gap-2.5">
            <div className="h-8 w-8">
              <Logoweb />
            </div>
            <span className="hidden text-sm font-semibold tracking-wide text-white sm:block">
              <Nameweb />
            </span>
          </Link>

          <div className="hidden items-center gap-8 lg:flex">
            {navLinks.map((l) => (
              <button
                key={l.id}
                onClick={() => scrollTo(l.id)}
                className="text-sm text-gray-400 transition-colors hover:text-white"
              >
                {l.label}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden sm:block">
              <LanguageSelector />
            </div>
            <button
              onClick={toLogin}
              className="hidden text-sm text-gray-300 transition-colors hover:text-white sm:block"
            >
              {t("login")}
            </button>
            <button
              onClick={toRegister}
              className="rounded-full bg-[#8b31e8] px-5 py-2 text-sm font-medium text-white transition-colors hover:bg-[#9d4bf0]"
            >
              {t("register")}
            </button>
            <button
              onClick={() => setMenuOpen(!menuOpen)}
              className="-mr-1 p-1 text-white lg:hidden"
              aria-label="menu"
            >
              {menuOpen ? <CloseIcon /> : <MenuIcon />}
            </button>
          </div>
        </nav>

        {menuOpen && (
          <div className="border-t border-white/10 bg-[#0a0512] px-5 py-2 lg:hidden">
            {navLinks.map((l) => (
              <button
                key={l.id}
                onClick={() => scrollTo(l.id)}
                className="block w-full border-b border-white/5 py-3.5 text-left text-sm text-gray-300 last:border-0"
              >
                {l.label}
              </button>
            ))}
            <div className="flex items-center justify-between gap-3 border-t border-white/10 py-3">
              <button
                onClick={toLogin}
                className="text-sm text-gray-300"
              >
                {t("login")}
              </button>
              <div className="sm:hidden">
                <LanguageSelector />
              </div>
            </div>
          </div>
        )}
      </header>

      {/* ── HERO ── */}
      <section className="relative overflow-hidden">
        {/* แสงม่วงจาง ๆ หลังรูป */}
        <div className="pointer-events-none absolute right-0 top-10 hidden h-[520px] w-[520px] rounded-full bg-[#8b31e8]/15 blur-[130px] lg:block" />

        <div className="relative mx-auto grid max-w-6xl items-center gap-14 px-5 pb-20 pt-10 sm:px-8 lg:grid-cols-[1fr_0.85fr] lg:pb-28 lg:pt-28">
          <div>
            {/* โลโก้ + ชื่อเว็บ เหนือหัวข้อ */}
            <div className="flex items-center gap-3">
              <div className="h-11 w-11 flex-shrink-0 lg:h-12 lg:w-12">
                <Logoweb />
              </div>
              <span className="text-xl font-semibold leading-tight text-white lg:text-2xl">
                <Nameweb />
              </span>
            </div>

            <p className="mt-6 text-xs uppercase tracking-[0.28em] text-[#b366f7]">
              {t("mw_hero_badge")}
            </p>

            <h1 className="mt-5 text-[2rem] font-semibold leading-[1.35] text-white sm:text-5xl lg:text-[3.2rem]">
              {t("mw_hero_title1")}
            </h1>
              <span className="block text-lg lg:text-4xl pt-3 text-gray-500">{t("mw_hero_title2")}</span>

            <p className="mt-8 max-w-xl text-sm leading-[1.9] text-gray-400 sm:text-base">
              {t("mw_hero_desc")}
            </p>

            <div className="mt-10 flex flex-wrap items-center gap-x-8 gap-y-4">
              <button
                onClick={toRegister}
                className="group inline-flex items-center gap-2 rounded-full bg-[#8b31e8] px-7 py-3.5 text-sm font-medium text-white transition-colors hover:bg-[#9d4bf0]"
              >
                {t("mw_hero_cta1")}
                <ArrowForwardIcon
                  sx={{ fontSize: 17 }}
                  className="transition-transform duration-200 group-hover:translate-x-1"
                />
              </button>
              <button
                onClick={() => scrollTo("markets")}
                className="group inline-flex items-center gap-1.5 text-sm text-gray-300 transition-colors hover:text-white"
              >
                {t("mw_hero_link")}
                <ArrowOutwardIcon
                  sx={{ fontSize: 15 }}
                  className="text-[#b366f7] transition-transform duration-200 group-hover:translate-x-0.5 group-hover:-translate-y-0.5"
                />
              </button>
            </div>

            {/* สินทรัพย์ยอดนิยม */}
            <div className="mt-12 block lg:flex items-center gap-4">
              <div className="flex -space-x-2.5">
                {assetChips.map((c) => (
                  <img
                    key={c.alt}
                    src={c.src}
                    alt={c.alt}
                    loading="lazy"
                    className="h-9 w-9 rounded-full ring-2 ring-[#060309]"
                  />
                ))}
              </div>
              <p className="pt-3 lg:pt-0 text-xs leading-relaxed text-gray-500">
                {t("mw_hero_assets")}
              </p>
            </div>
          </div>

          {/* ภาพแอปเทรดบนมือถือ */}
          <div className="relative mt-4 lg:mt-0">
            <LazyLoadImage
              src={phone_trade}
              alt="trading app"
              className="mx-auto w-full max-w-[300px] drop-shadow-[0_25px_60px_rgba(139,49,232,0.28)] sm:max-w-[380px] lg:max-w-none"
            />
          </div>
        </div>
      </section>

      {/* ── TICKER ── */}
      <div className="border-y border-white/10 bg-[#0b0616]">
        <CryptoCarousel />
      </div>

      {/* ── STATS ── */}
      <section className="mx-auto max-w-6xl px-5 sm:px-8">
        <dl className="grid grid-cols-2 border-b border-white/10 sm:grid-cols-4">
          {stats.map((s, i) => (
            <div
              key={i}
              className="border-white/10 px-1 py-9 sm:border-l sm:first:border-l-0 sm:pl-7 sm:first:pl-0"
            >
              <dt className="text-[2rem] font-semibold leading-none text-white">
                {s.val}
                {s.unit && (
                  <span className="ml-1 text-sm font-normal text-[#b366f7]">
                    {s.unit}
                  </span>
                )}
              </dt>
              <dd className="mt-3 max-w-[13rem] text-xs leading-relaxed text-gray-500">
                {s.label}
              </dd>
            </div>
          ))}
        </dl>
      </section>

      {/* ── MARKETS ── */}
      <section
        id="markets"
        className="mx-auto max-w-6xl scroll-mt-20 px-5 py-24 sm:px-8 lg:py-32"
      >
        <div className="grid gap-8 lg:grid-cols-[20rem_1fr] lg:gap-16">
          <div className="lg:sticky lg:top-28 lg:self-start">
            <p className="text-xs uppercase tracking-[0.28em] text-[#b366f7]">
              {t("mw_markets_eyebrow")}
            </p>
            <h2 className="mt-5 text-2xl font-semibold leading-[1.4] text-white sm:text-3xl">
              {t("mw_markets_title")}
            </h2>
            <p className="mt-5 text-sm leading-[1.9] text-gray-500">
              {t("mw_markets_desc")}
            </p>
          </div>

          <div className="border-t border-white/10">
            {markets.map((m, i) => {
              const Icon = m.icon;
              return (
              <button
                key={i}
                onClick={toRegister}
                className="group flex w-full items-start gap-4 border-b border-white/10 py-6 text-left transition-colors hover:bg-white/[0.02] sm:gap-6"
              >
                <span className="flex h-11 w-11 flex-shrink-0 items-center justify-center rounded-xl border border-white/10 bg-white/[0.03] text-[#b366f7] transition-colors group-hover:border-[#8b31e8]/40 group-hover:bg-[#8b31e8]/10">
                  <Icon sx={{ fontSize: 21 }} />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-base font-medium text-white sm:text-lg">
                    {m.name}
                  </span>
                  <span className="mt-1.5 block text-sm leading-relaxed text-gray-500">
                    {m.txt}
                  </span>
                </span>
                <span className="flex flex-shrink-0 items-center gap-3 pt-3">
                  <span className="hidden whitespace-nowrap text-xs text-gray-500 sm:inline">
                    {m.count} {t("mw_market_instruments")}
                  </span>
                  <ArrowOutwardIcon
                    sx={{ fontSize: 16 }}
                    className="text-gray-700 transition-colors group-hover:text-[#b366f7]"
                  />
                </span>
              </button>
              );
            })}
          </div>
        </div>
      </section>

      {/* ── WHY ── */}
      <section
        id="why"
        className="scroll-mt-20 border-y border-white/10 bg-[#0b0616]"
      >
        <div className="mx-auto max-w-6xl px-5 py-24 sm:px-8 lg:py-32">
          <p className="text-xs uppercase tracking-[0.28em] text-[#b366f7]">
            {t("mw_why_eyebrow")}
          </p>
          <h2 className="mt-5 max-w-2xl text-2xl font-semibold leading-[1.4] text-white sm:text-3xl">
            {t("mw_why_title")}
          </h2>

          <div className="mt-16 grid gap-x-14 gap-y-12 sm:grid-cols-2 lg:grid-cols-3">
            {reasons.map((r, i) => {
              const Icon = r.icon;
              return (
                <div key={i}>
                  <div className="flex items-center gap-3">
                    <Icon sx={{ fontSize: 22 }} className="text-[#b366f7]" />
                    <span className="text-xs text-gray-600">{num(i)}</span>
                  </div>
                  <h3 className="mt-4 text-base font-medium text-white">
                    {r.head}
                  </h3>
                  <p className="mt-2.5 text-sm leading-[1.9] text-gray-500">
                    {r.txt}
                  </p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* ── PLATFORM ── */}
      <section
        id="platform"
        className="mx-auto max-w-6xl scroll-mt-20 px-5 py-24 sm:px-8 lg:py-32"
      >
        <div className="grid items-center gap-12 lg:grid-cols-[0.9fr_1.1fr] lg:gap-16">
          <div>
            <p className="text-xs uppercase tracking-[0.28em] text-[#b366f7]">
              {t("mw_platform_eyebrow")}
            </p>
            <h2 className="mt-5 text-2xl font-semibold leading-[1.4] text-white sm:text-3xl">
              {t("mw_platform_title")}
            </h2>
            <p className="mt-6 text-sm leading-[1.9] text-gray-500 sm:text-base">
              {t("mw_platform_desc")}
            </p>

            <ul className="mt-8 border-t border-white/10">
              {platformPoints.map((p, i) => (
                <li
                  key={i}
                  className="flex items-start gap-4 border-b border-white/10 py-4"
                >
                  <CheckIcon
                    sx={{ fontSize: 17 }}
                    className="mt-0.5 flex-shrink-0 text-[#b366f7]"
                  />
                  <span className="text-sm leading-relaxed text-gray-300">
                    {p}
                  </span>
                </li>
              ))}
            </ul>

            <button
              onClick={toRegister}
              className="group mt-8 inline-flex items-center gap-2 text-sm text-white transition-colors hover:text-[#b366f7]"
            >
              {t("mw_platform_cta")}
              <ArrowForwardIcon
                sx={{ fontSize: 16 }}
                className="transition-transform group-hover:translate-x-1"
              />
            </button>
          </div>

          {/* ภาพแพลตฟอร์มบนคอมและมือถือ */}
          <div className="relative">
            <div className="pointer-events-none absolute inset-x-8 top-8 h-64 rounded-full bg-[#8b31e8]/12 blur-[110px]" />
            <LazyLoadImage
              src={trade_desktop}
              alt="trading platform"
              className="relative w-full drop-shadow-[0_30px_60px_rgba(0,0,0,0.55)]"
            />
          </div>
        </div>
      </section>

      {/* ── STEPS ── */}
      <section
        id="start"
        className="scroll-mt-20 border-y border-white/10 bg-[#0b0616]"
      >
        <div className="mx-auto max-w-6xl px-5 py-24 sm:px-8 lg:py-32">
          <p className="text-xs uppercase tracking-[0.28em] text-[#b366f7]">
            {t("mw_steps_eyebrow")}
          </p>
          <h2 className="mt-5 text-2xl font-semibold leading-[1.4] text-white sm:text-3xl">
            {t("mw_steps_title")}
          </h2>

          <div className="mt-14 border-t border-white/10">
            {steps.map((s, i) => {
              const Icon = s.icon;
              return (
                <div
                  key={i}
                  className="grid gap-3 border-b border-white/10 py-7 sm:grid-cols-[5.5rem_14rem_1fr] sm:items-center sm:gap-6"
                >
                  <span className="flex items-center gap-3">
                    <span className="text-sm text-[#b366f7]">{num(i)}</span>
                    <Icon sx={{ fontSize: 22 }} className="text-gray-500" />
                  </span>
                  <h3 className="text-base font-medium text-white sm:text-lg">
                    {s.head}
                  </h3>
                  <p className="text-sm leading-[1.9] text-gray-500">{s.txt}</p>
                </div>
              );
            })}
          </div>

          <div className="mt-10 flex flex-wrap gap-x-10 gap-y-3">
            {assurances.map((a) => (
              <span
                key={a}
                className="flex items-center gap-2 text-xs text-gray-500"
              >
                <span className="h-1 w-1 rounded-full bg-[#b366f7]" />
                {a}
              </span>
            ))}
          </div>
        </div>
      </section>

      {/* ── FAQ ── */}
      <section className="mx-auto max-w-6xl px-5 py-24 sm:px-8 lg:py-32">
        <div className="grid gap-8 lg:grid-cols-[20rem_1fr] lg:gap-16">
          <div>
            <h2 className="text-2xl font-semibold leading-[1.4] text-white sm:text-3xl">
              {t("mw_faq_title")}
            </h2>
            <p className="mt-5 text-sm leading-[1.9] text-gray-500">
              {t("mw_faq_more")}
            </p>
            <button
              onClick={openChat}
              className="mt-3 text-sm text-[#b366f7] underline-offset-4 hover:underline"
            >
              {t("contactus")}
            </button>
          </div>

          <div className="border-t border-white/10">
            {faqs.map((f, i) => (
              <div key={i} className="border-b border-white/10">
                <button
                  onClick={() => setOpenFaq(openFaq === i ? -1 : i)}
                  className="flex w-full items-start justify-between gap-6 py-5 text-left"
                >
                  <span className="text-sm font-medium leading-relaxed text-white sm:text-base">
                    {f.q}
                  </span>
                  <AddIcon
                    sx={{ fontSize: 18 }}
                    className={`mt-0.5 flex-shrink-0 text-gray-500 transition-transform duration-300 ${
                      openFaq === i ? "rotate-45 text-[#b366f7]" : ""
                    }`}
                  />
                </button>
                {openFaq === i && (
                  <p className="max-w-2xl pb-6 pr-10 text-sm leading-[1.9] text-gray-500">
                    {f.a}
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── CTA ── */}
      <section className="border-t border-white/10 bg-[#0b0616]">
        <div className="mx-auto max-w-3xl px-5 py-24 text-center sm:px-8 lg:py-32">
          <h2 className="text-2xl font-semibold leading-[1.4] text-white sm:text-4xl">
            {t("mw_cta_title")}
          </h2>
          <p className="mx-auto mt-6 max-w-lg text-sm leading-[1.9] text-gray-500 sm:text-base">
            {t("mw_cta_desc")}
          </p>
          <div className="mt-10 flex flex-wrap items-center justify-center gap-x-8 gap-y-4">
            <button
              onClick={toRegister}
              className="group inline-flex items-center gap-2 rounded-full bg-[#8b31e8] px-8 py-3.5 text-sm font-medium text-white transition-colors hover:bg-[#9d4bf0]"
            >
              {t("signupUse")}
              <ArrowForwardIcon
                sx={{ fontSize: 17 }}
                className="transition-transform group-hover:translate-x-1"
              />
            </button>
            <button
              onClick={toLogin}
              className="text-sm text-gray-300 transition-colors hover:text-white"
            >
              {t("login")}
            </button>
          </div>
        </div>
      </section>

      {/* ── FOOTER ── */}
      <footer className="border-t border-white/10 bg-[#030106]">
        <div className="mx-auto max-w-6xl px-5 py-16 sm:px-8">
          <div className="grid gap-10 sm:grid-cols-2 lg:grid-cols-4">
            <div>
              <div className="flex items-center gap-2.5">
                <div className="h-8 w-8">
                  <Logoweb />
                </div>
                <span className="text-sm font-semibold text-white">
                  <Nameweb />
                </span>
              </div>
              <p className="mt-5 max-w-xs text-xs leading-relaxed text-gray-600">
                {t("mw_footer_tagline")}
              </p>
            </div>

            <div>
              <h4 className="text-xs uppercase tracking-wider text-gray-500">
                {t("mw_footer_markets")}
              </h4>
              <ul className="mt-4 space-y-3 text-sm text-gray-400">
                {markets.slice(0, 4).map((m, i) => (
                  <li key={i}>
                    <button
                      onClick={() => scrollTo("markets")}
                      className="transition-colors hover:text-white"
                    >
                      {m.name}
                    </button>
                  </li>
                ))}
              </ul>
            </div>

            <div>
              <h4 className="text-xs uppercase tracking-wider text-gray-500">
                {t("mw_footer_company")}
              </h4>
              <ul className="mt-4 space-y-3 text-sm text-gray-400">
                <li>
                  <button
                    onClick={() => scrollTo("why")}
                    className="transition-colors hover:text-white"
                  >
                    {t("mw_nav_why")}
                  </button>
                </li>
                <li>
                  <button
                    onClick={() => scrollTo("platform")}
                    className="transition-colors hover:text-white"
                  >
                    {t("mw_nav_platform")}
                  </button>
                </li>
                {websiteURL ? (
                  <li>
                    <a
                      href={websiteURL}
                      target="_blank"
                      rel="noreferrer"
                      className="transition-colors hover:text-white"
                    >
                      {t("mw_footer_website")}
                    </a>
                  </li>
                ) : null}
              </ul>
            </div>

            <div>
              <h4 className="text-xs uppercase tracking-wider text-gray-500">
                {t("mw_footer_support")}
              </h4>
              <ul className="mt-4 space-y-3 text-sm text-gray-400">
                <li>
                  <button
                    onClick={openChat}
                    className="transition-colors hover:text-white"
                  >
                    {t("contactus")}
                  </button>
                </li>
                {gmailURL ? (
                  <li>
                    <a
                      href={`mailto:${gmailURL}`}
                      className="break-all transition-colors hover:text-white"
                    >
                      {gmailURL}
                    </a>
                  </li>
                ) : null}
                <li>
                  <button
                    onClick={toRegister}
                    className="transition-colors hover:text-white"
                  >
                    {t("mw_nav_start")}
                  </button>
                </li>
              </ul>
            </div>
          </div>

          <div className="mt-14 border-t border-white/10 pt-8">
            <p className="text-xs leading-[1.9] text-gray-600">
              <span className="text-gray-400">{t("risk_warning")}</span> :{" "}
              {t("footertxt2")}
            </p>
            <p className="mt-3 text-xs leading-[1.9] text-gray-600">
              {t("footertxt4")}
            </p>
          </div>

          <div className="mt-10 flex flex-col gap-3 border-t border-white/10 pt-8 sm:flex-row sm:items-center sm:justify-between">
            <p className="text-xs text-gray-600">
              © 2026 {webname}. {t("mw_footer_rights")}
            </p>
            <p className="text-xs text-gray-600">
              {t("mw_footer_terms")} · {t("mw_footer_privacy")}
            </p>
          </div>
        </div>
      </footer>

      {/* ── CHATWOOT ── */}
      {isOpen && isMobile && isready ? (
        <button
          className="fixed right-10 top-5 z-[2147483001] h-5 w-5 text-black"
          onClick={handleToggle}
        >
          {t("close")}
        </button>
      ) : null}

      <ChatwootComponent2 />

      <div className="woot--bubble-holder">
        <button
          className="woot-widget-bubble woot-elements--right"
          title={isOpen ? "Close chat window" : "Open chat window"}
          onClick={handleToggle}
        >
          <svg
            id="woot-widget-bubble-icon"
            width="24"
            height="24"
            viewBox="0 0 240 240"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M240.808 240.808H122.123C56.6994 240.808 3.45695 187.562 3.45695 122.122C3.45695 56.7031 56.6994 3.45697 122.124 3.45697C187.566 3.45697 240.808 56.7031 240.808 122.122V240.808Z"
              fill="#FFFFFF"
            />
          </svg>
        </button>
      </div>
    </div>
  );
}
