import React, { useState, useEffect } from "react";
import Lottie from "lottie-react";

import TabLogin from "./Mainsite/TabLogin";
import login_bg from "../../image/login_bg.webp";
// import bg_login from "../../image/bg_login.jpg";
import bg_login from "../../image/bg_login2.jpg";

import Ani_loginTrade from "../../Json/ani_loginTrade.json";
import ani_phoneGraph from "../../Json/ani_phoneGraph.json";

import { HomeIcon } from "@heroicons/react/24/solid";

import { Link, useNavigate, useParams } from "react-router-dom";
import mobile_cover from "../../image/mobile_login_cover.jpg";

import svg_footer1 from "../../icon/svg_footer/borker1.svg";
import svg_footer2 from "../../icon/svg_footer/borker2.svg";
import svg_footer3 from "../../icon/svg_footer/borker3.svg";
import svg_footer4 from "../../icon/svg_footer/borker4.svg";

import ios_android from "../../image/icon_android_ios.png";
import { useTranslation } from "react-i18next";
import { LazyLoadImage } from "react-lazy-load-image-component";
import ChatwootComponent from "./ChatwootWidget";
import Logoweb from "../../Function/Logoweb";
import Nameweb from "../../Function/Nameweb";
import LanguageSelector from "../language-selector";
import ChatwootComponent2 from "./ChatwootWidget2";

function Login_user() {
  const { t } = useTranslation();
  let { id } = useParams();
  const navigate = useNavigate();
  const [openTab, setOpenTab] = useState(Number(id) || 2);
  const [isOn, setIsOn] = useState(true);

  const isMobile = window.innerWidth <= 768 ? true : false;
  const [isOpen, setIsOpen] = useState(false);
  const [isready, setIsready] = useState(true);

  const handleToggle = () => {
    const newState = !isOpen;
    window.$chatwoot.toggle(newState ? "open" : "close");
    setIsOpen(newState);
  };
  useEffect(() => {
    const handleChatwootReady = async () => {
      setIsready(false);
    };
    window.addEventListener("chatwoot:ready", handleChatwootReady);

    return () => {
      window.removeEventListener("chatwoot:ready", handleChatwootReady);
    };
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);
  const toHome = () => {
    navigate("/");
  };

  const toggleSwitch = () => {
    setIsOn(!isOn);
  };

  return (
    <div className="bg-gradient-to-b from-[#060309] to-[#180d28] min-h-screen pb-20">
      <div className="w-full ">
        <div className="flex sticky top-0 z-50">
          <nav className="flex justify-between w-full h-14 md:h-16 z-50 bg-gray-100  shadow-lg overflow-hidden bg_nav_1">
            <Link to="/" className="flex items-center">
              <div className="flex">
                <div className="  text-center  h-10 lg:h-11 mx-2 object-contain ">
                  <Logoweb />
                </div>
                <div className="text-white my-auto text-shadow-3 block">
                  <Nameweb />
                </div>
              </div>
            </Link>
            <div className=" flex justify-end my-4 md:m-4 items-center whitespace-nowrap">
              <div className="flex items-center mr-1">
                <LanguageSelector />
              </div>
            </div>
          </nav>
        </div>

        <div className="w-full ">
          <div
            className="w-full px-1 lg:px-16 mx-auto   bg-cover bg-no-repeat rounded-xl "
            // style={{ backgroundImage: `url(${bg_login})` }}
          >
            <div className="w-full flex justify-center mx-auto ">
              <div className="w-full p-4 lg:w-1/2 block align-middle justify-center rounded-xl ">
                <TabLogin openTab={openTab} setOpenTab={setOpenTab} />
              </div>

            </div>
          </div>
        </div>

                {isOpen && isMobile&&isready? (
        <button
          className="fixed top-5 right-10 text-black w-5 h-5"
          style={{ zIndex: "2147483001" }}
          onClick={handleToggle}
        >
          {t("close")}
        </button>
      ) : (
        <></>
      )}

      <ChatwootComponent2 />

      <div className="woot--bubble-holder">
        <button
          className="woot-widget-bubble woot-elements--right"
          title={isOpen ? "Close chat window" : "Open chat window"}
          onClick={handleToggle}
        >
          <svg
            id="woot-widget-bubble-icon"
            width="24"
            height="24"
            viewBox="0 0 240 240"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M240.808 240.808H122.123C56.6994 240.808 3.45695 187.562 3.45695 122.122C3.45695 56.7031 56.6994 3.45697 122.124 3.45697C187.566 3.45697 240.808 56.7031 240.808 122.122V240.808Z"
              fill="#FFFFFF"
            />
          </svg>
        </button>
        
      </div>
      </div>
    </div>
  );
}

export default Login_user;
