import React, { useState, useEffect } from "react";
import API_URL from "../../../config/api";
import cerficate_img from '../../../image/cerficate_image.jpg'
import { LazyLoadImage } from "react-lazy-load-image-component";

function Aboutus() {
  const [aboutus, setAboutus] = useState("");
  useEffect(() => {
    getWebUrl();
  }, []);
  const getWebUrl = async () => {
    await API_URL.get(`api/weburl/getaboutus`)
      .then((res) => {
        const allweburl = res.data;
        if (allweburl.length !== 0) {
          const resaboutus = allweburl.find(({ name }) => name === "aboutus");
          setAboutus(resaboutus.nameurl);
        }
        return res.data;
      })
      .catch((err) => {
        console.log(err);
      });
  };
  return (
    <div className="p-2 lg:p-1">
      <div className="w-full lg:w-3/6 bg-[#1f1136] rounded-xl shadow-md mx-auto px-2 py-1 lg:px-5 lg:py-2 text-white">
        <p>{aboutus}</p>

      </div>
              <LazyLoadImage src={cerficate_img} alt="cerficate" className="w-full lg:w-3/6 mx-auto pt-3 lg:pt-8" />
    </div>
  );
}

export default Aboutus;
