import React, { useState, useEffect, useRef, createContext } from "react";
import { Link, Route, Routes, useLocation } from "react-router-dom";
import Lottie from "lottie-react";

import { ConfigProvider, theme } from "antd";
import HomeComponent from "./MainUser/Home";
import loading_anime from "../../Json/loading_animetion4.json";
import Mylogo from "../../image/Bitcoin-SV-logo-white.png";

import dayjs from "dayjs";

import Home from "@mui/icons-material/Home";
import QueryStatsIcon from "@mui/icons-material/QueryStats";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";

import RestoreIcon from "@mui/icons-material/Restore";

import numberFormat from "../../Function/NumberFormat2float";

import social1 from "../../icon/logo-facebook2.webp";
import social2 from "../../icon/line_logo_icon_147270.webp";
import social3 from "../../icon/website-icon-11.png";
import social4 from "../../icon/gmail_ic.png";
import forex_date_icon from "../../icon/forexdate.png";

import svg_footer1 from "../../icon/svg_footer/borker1.svg";
import svg_footer2 from "../../icon/svg_footer/borker2.svg";
import svg_footer3 from "../../icon/svg_footer/borker3.svg";
import svg_footer4 from "../../icon/svg_footer/borker4.svg";

import ios_android from "../../image/icon_android_ios.png";

import API_URL from "../../config/api";
import Account from "./Account/Account";
import config from "../../config/configapi";
import Trade from "./Trade/Trade";
import Deposit from "./MainUser/Deposit";
import History_main from "./Trade_history/History_main";
import Verify from "./Account/Verify";
import Edit_profile from "./Account/Edit_profile";
import Transaction from "./Transaction/Transaction";
import Withdraw from "./Account/Withdraw";
import { WebSocketUserProvider } from "./WebSocketUser";
import LanguageSelector from "../language-selector";
import { useTranslation } from "react-i18next";
import ChatwootComponent from "./ChatwootWidget";
import { LazyLoadImage } from "react-lazy-load-image-component";
import CountdownTime from "./CountdownTime";
import Logoweb from "../../Function/Logoweb";
import Nameweb from "../../Function/Nameweb";
import Aboutus from "./Account/Aboutus";
import { useCookies } from "react-cookie";
import Swal from "sweetalert2";
import utc from "dayjs/plugin/utc";
import timezone from "dayjs/plugin/timezone";
import { TOKEN_KEY } from "../../config/token_key";
import NavigationMenu from "./NavBottom/NavigationMenu";
import ChatwootComponent2 from "./ChatwootWidget2";

export const DashboardContext = createContext();
function Dashboard() {
  const { t } = useTranslation();

  const { defaultAlgorithm, darkAlgorithm } = theme;
  const [loading, setLoading] = useState(false);
  const [userdata, setUserdata] = useState({});
  const URL_HOST = `${config.API_SERVER}`;

  const [facebookURL, setFacebookURL] = useState("");
  const [lineURL, setLineURL] = useState("");
  const [websiteURL, setWebsiteURL] = useState("");
  const [gmailURL, setGmailURL] = useState("");

  const [payrate, setPayrate] = useState([]);
  const minTime = [3, 5, 15, 30];

  const [idbank, setIdbank] = useState("");
  const [codebank, setCodebank] = useState("");
  const [namebank, setNamebank] = useState("");
  const [imgbank, setImgbank] = useState(null);
  const [bankdetail, setBankdetail] = useState("");
  const [value, setValue] = useState(0);

  const [tradinglist, setTradinglist] = useState([]);
  const [tradinglistloading, setTradinglistLoading] = useState(true);

  const [userId] = useState(JSON.parse(localStorage.getItem(`${TOKEN_KEY}Id`)));
  let pathname = useLocation();

  const [checkForexOpen, setCheckForexOpen] = useCookies(["checkForexOpen"]);
  const [isCheckForexOpen, setIsCheckForexOpen] = useState(
    checkForexOpen.checkForexOpen
      ? checkForexOpen.checkForexOpen.toString()
      : "1"
  );

  const isMobile = window.innerWidth <= 768 ? true : false;
  const [isOpen, setIsOpen] = useState(false);
  const [isready, setIsready] = useState(true);

  const handleToggle = () => {
    const newState = !isOpen;
    window.$chatwoot.toggle(newState ? "open" : "close");
    setIsOpen(newState);
  };
  useEffect(() => {
    const handleChatwootReady = async () => {
      setIsready(false);
    };
    window.addEventListener("chatwoot:ready", handleChatwootReady);

    return () => {
      window.removeEventListener("chatwoot:ready", handleChatwootReady);
    };
  }, []);

  dayjs.extend(utc);
  dayjs.extend(timezone);

  const now = dayjs().tz("Asia/Bangkok");
  const day = now.day();
  const hour = now.hour();
  const minute = now.minute();

  useEffect(() => {
    get_user();
    getWebUrl();
    getPayrate();
    get_OneUserTrading();
    CheckForexDate();
    window.scrollTo(0, 0);
  }, [pathname]);

  const isForexOpen =
    (day === 1 && (hour > 4 || (hour === 4 && minute >= 0))) ||
    (day >= 2 && day <= 5) ||
    (day === 6 && (hour < 4 || (hour === 4 && minute === 0)));

  const CheckForexDate = async () => {
    if (isForexOpen) {
      setCheckForexOpen("checkForexOpen", "1", {
        path: `/`,
      });
      setIsCheckForexOpen("1");
      return;
    } else if (isCheckForexOpen === "1") {
      await Swal.fire({
        background: "#130a20",
        title: `<img src=${forex_date_icon} class="h-16 lg:h-28 mx-auto mt-5"/>`,
        html: `
                <p class="mb-2 text-white text-sm lg:text-base mt-2">${t(
                  "forex_open_date"
                )} </p>
              `,
        focusConfirm: false,
        showDenyButton: true,
        showConfirmButton: false,
        allowOutsideClick: false,
        denyButtonText: `
               <p class="m-auto text-center px-3">${t("close")}</p>
              `,

        customClass: {
          container: "p-0",
          popup: "p-1",
          title: "p-1",
          htmlContainer: "p-2 m-0",
          confirmButton: "w-1/4",
          footer: "p-1",
        },
      });
      setCheckForexOpen("checkForexOpen", "2", {
        path: `/`,
      });
      setIsCheckForexOpen("2");
    } else {
      return;
    }
  };

  const getPayrate = async () => {
    setPayrate([]);
    await API_URL.get(`api/percentrate/allpercentrate`)
      .then((res) => {
        const allpayrate = res.data;
        const newStateArray = [];
        if (allpayrate.length !== 0) {
          allpayrate.map((payrate, index) => {
            newStateArray.push({
              id: payrate.id,
              percent: payrate.percent,
              countTime: minTime[index],
            });
          });
        }
        setPayrate(newStateArray);

        return res.data;
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const getWebUrl = async () => {
    await API_URL.get(`api/weburl/getallweburl`)
      .then((res) => {
        const allweburl = res.data;
        if (allweburl.length !== 0) {
          const resFacebook = allweburl.find(({ name }) => name === "facebook");
          setFacebookURL(resFacebook.nameurl);
          const resLine = allweburl.find(({ name }) => name === "line");
          setLineURL(resLine.nameurl);
          const resWebsite = allweburl.find(({ name }) => name === "website");
          setWebsiteURL(resWebsite.nameurl);
          const resGmail = allweburl.find(({ name }) => name === "gmail");
          setGmailURL(resGmail.nameurl);
          const residbank = allweburl.find(({ name }) => name === "idbank");
          setIdbank(residbank.nameurl);
          const rescodebank = allweburl.find(({ name }) => name === "codebank");
          setCodebank(rescodebank.nameurl);
          const resnamebank = allweburl.find(({ name }) => name === "namebank");
          setNamebank(resnamebank.nameurl);
          const resimgbank = allweburl.find(({ name }) => name === "imgbank");
          setImgbank(URL_HOST + resimgbank.nameurl);
          const resbankdetail = allweburl.find(
            ({ name }) => name === "bankdetail"
          );
          setBankdetail(resbankdetail.nameurl);
        }
        return res.data;
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const get_user = async () => {
    // setLoading(true);
    await API_URL.get(`api/people/oneUserdata/${userId}`)
      .then((res) => {
        const getoneuser = res.data.user;

        setUserdata(getoneuser);
      })
      .catch((err) => {
        logout();
      });
    // setLoading(false);
  };

  const logout = () => {
    localStorage.removeItem(`${TOKEN_KEY}Id`);
    window.location.href = `/login`;
  };

  const get_OneUserTrading = async () => {
    setTradinglist([]);
    setTradinglistLoading(true);
    await API_URL.get(`api/tradelist/getoneusertrading/${userId}`)
      .then((res) => {
        const getalluser = res.data;

        if (getalluser.length !== 0) {
          getalluser.sort((a, b) => (b.createdAt > a.createdAt ? 1 : -1));
          setTradinglist(getalluser);

          console.log(getalluser.map((trading)=>trading.timeRemainingSeconds));
        }
      })

      .catch((err) => {
        console.log(err);
      });
    setTradinglistLoading(false);
  };

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  return (
    <WebSocketUserProvider>
      <ConfigProvider
      theme={{
        algorithm: darkAlgorithm,
        token: {
          colorPrimary: "#a855f7",
          colorInfo: "#a855f7",
          colorLink: "#c084fc",
        },
      }}
      >
        <DashboardContext.Provider
          value={{
            payrate,
            userId,
            tradinglist,
            tradinglistloading,
            get_OneUserTrading,
            get_user,
            userdata,
          }}
        >
          {tradinglist.length !== 0 &&
            tradinglist.map((trading, index) => (
              <div key={trading.id}>
                {/* <CountdownTime
                   date={Math.max(0, dayjs(trading.closing_time).diff(dayjs().tz("Asia/Bangkok"), 'second'))} 
                  id={trading.id}
                /> */}
                {/* <CountdownTime
                  date={Math.max(
                    0,
                    dayjs(trading.closing_time).tz("Asia/Bangkok").diff(dayjs().tz("Asia/Bangkok"),"second")
                    // dayjs(trading.closing_time).diff(dayjs().tz("Asia/Yangon"), "second")

                  )}
                  id={trading.id}
                /> */}
                <CountdownTime
                  date={trading.timeRemainingSeconds}
                  id={trading.id}
                />
              </div>
            ))}

          <div className="bg_main">
            <div className="flex sticky top-0 z-50">
              <nav className="flex justify-between w-full h-14 md:h-14 z-50   shadow-lg overflow-hidden bg_nav_1">
                <Link to="/login/" className="flex items-center">
                  <div className="flex">
                    <div className="  text-center  h-8 lg:h-11 mx-2 object-contain ">
                      <Logoweb />
                    </div>
                    <div className="text-white my-auto text-shadow-3">
                      <Nameweb />
                    </div>
                  </div>
                </Link>
                <div className=" flex">
                  <div className="hidden lg:grid grid-cols-4  self-center mr-5 gap-x-1 w-96">
                    <Link
                      to="/login/"
                      className={
                        (pathname.pathname === "/login/"
                          ? "text-white bg-gradient-to-l from-purple-700 to-purple-500"
                          : "text-white ") +
                        " m-auto hover:bg-purple-600 rounded-md w-full text-shadow-3 py-1"
                      }
                    >
                      <div className="block mx-auto text-center ">
                        <Home
                          style={{ filter: "drop-shadow(1px 1px 2px black)" }}
                        />
                        <p className="text-sm">{t("home")}</p>
                      </div>
                    </Link>
                    <Link
                      to="/login/trade"
                      className={
                        (pathname.pathname === "/login/trade"
                          ? "text-white bg-gradient-to-l from-purple-700 to-purple-500"
                          : "text-white ") +
                        " m-auto hover:bg-purple-600 rounded-md w-full text-shadow-3 py-1"
                      }
                    >
                      <div className="block mx-auto text-center ">
                        <QueryStatsIcon
                          style={{ filter: "drop-shadow(1px 2px 2px black)" }}
                        />
                        <p className="text-sm">{t("trade")}</p>
                      </div>
                    </Link>
                    <Link
                      to="/login/trade_history"
                      className={
                        (pathname.pathname === "/login/trade_history"
                          ? "text-white bg-gradient-to-l from-purple-700 to-purple-500"
                          : "text-white ") +
                        " m-auto hover:bg-purple-600 rounded-md w-full text-shadow-3 py-1"
                      }
                    >
                      <div className="block mx-auto text-center ">
                        <RestoreIcon
                          style={{ filter: "drop-shadow(1px 1px 2px black)" }}
                        />
                        <p className="text-sm">{t("trade_history")}</p>
                      </div>
                    </Link>
                    <Link
                      to="/login/account"
                      className={
                        (pathname.pathname === "/login/account"
                          ? "text-white bg-gradient-to-l from-purple-700 to-purple-500"
                          : "text-white ") +
                        " m-auto hover:bg-purple-600 rounded-md w-full text-shadow-3 py-1"
                      }
                    >
                      <div className="block mx-auto text-center ">
                        <AccountCircleIcon
                          style={{ filter: "drop-shadow(1px 1px 2px black)" }}
                        />
                        <p className="text-sm">{t("info")}</p>
                      </div>
                    </Link>
                  </div>
                  <div className="bg-gradient-to-l from-[#2d1160] to-[#0e0719]  my-1 mr-3 rounded-xl hidden lg:flex justify-center align-middle shadow-xl items-center">
                    <p className="text-white px-5 my-auto text-shadow-3">
                      {t("wallet")} : &nbsp;&nbsp;
                      {numberFormat(userdata.credit)} USDT &nbsp;
                    </p>
                  </div>
                  <div className="my-auto mr-1">
                    <LanguageSelector />
                  </div>
                </div>
              </nav>
            </div>
            <NavigationMenu />
            <div
              className="h-auto pt-1 lg:mt-1 "
              style={{
                // backgroundImage: `/img/bg10.jpg`,
                backgroundRepeat: "no-repeat",
                backgroundAttachment: "fixed",
                backgroundSize: "cover",
                minHeight: "100vh",
              }}
            >
              {loading ? (
                <div className=" w-1/6 mx-auto flex justify-center items-center min-h-screen">
                  <Lottie animationData={loading_anime} loop={true} />
                </div>
              ) : (
                <Routes>
                  <Route
                    path="/"
                    element={<HomeComponent userdata={userdata} />}
                  />
                  <Route
                    path="/deposit"
                    element={
                      <Deposit
                        userdata={userdata}
                        bankdetail={bankdetail}
                        imgbank={imgbank}
                      />
                    }
                  />
                  <Route
                    path="/withdraw"
                    element={<Withdraw userdata={userdata} />}
                  />

                  <Route path="/trade" element={<Trade />} />
                  <Route
                    path="/trade_history"
                    element={<History_main userdata={userdata} />}
                  />
                  <Route
                    path="/transaction_history"
                    element={<Transaction />}
                  />
                  <Route
                    path="/account"
                    element={
                      <Account
                        userdata={userdata}
                        get_user={get_user}
                        lineURL={lineURL}
                      />
                    }
                  />
                  <Route
                    path="/verify"
                    element={<Verify userdata={userdata} />}
                  />
                  <Route
                    path="/edit_profile"
                    element={<Edit_profile userdata={userdata} />}
                  />
                  <Route path="/aboutus" element={<Aboutus />} />
                </Routes>
              )}
            </div>
          </div>
          <footer
            className="px-3 md:px-9 py-5 text-center bg-gradient-to-b from-[#0e0719] to-[#35107a]"
            style={{
              backgroundRepeat: "no-repeat",
              backgroundAttachment: "scroll",
              backgroundSize: "cover",
            }}
          >
            <div className="grid grid-cols-1  mb-3">
                    <div className="flex justify-center align-middle items-center">
                      <div className="  text-center  h-16 lg:h-16 mx-2 object-contain ">
                        <Logoweb />
                      </div>
                      <div className="text-white my-auto">
                        <Nameweb />
                      </div>
                    </div>

                  </div>
                  <div className="w-full md:w-full mx-auto">
                    <p className="text-base md:text-sm text-center my-2 text-white">
                      {t("moment3")}
                    </p>
                  </div>
                  <div className="w-full md:w-2/3 mx-auto">
                    <p className="text-sm md:text-base text-center text-white">{t("moment1")}</p>
                  </div>
        
                  <div className="bg-white/20 h-0.5 my-5 w-5/6 mx-auto"></div>
        
                  <div className=" w-full lg:w-2/3 text-left mx-auto">
                    <p className="text-gray-500 text-xs md:text-sm">
                      <strong>{t("risk_warning")}</strong> : {t("footertxt2")}
                    </p>
                  </div>
        
                  <div className="mt-3 text-white text-xs lg:text-base pb-16 lg:pb-1">
                    <p>© 2018. ALL RIGHTS RESERVED.</p>
                  </div>
            {isOpen && isMobile && isready ? (
              <button
                className="fixed top-5 right-10 text-black w-5 h-5"
                style={{ zIndex: "2147483001" }}
                onClick={handleToggle}
              >
                {t("close")}
              </button>
            ) : (
              <></>
            )}

            <ChatwootComponent2 />

            <div className="woot--bubble-holder">
              <button
                className="woot-widget-bubble woot-elements--right"
                title={isOpen ? "Close chat window" : "Open chat window"}
                onClick={handleToggle}
              >
                <svg
                  id="woot-widget-bubble-icon"
                  width="24"
                  height="24"
                  viewBox="0 0 240 240"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M240.808 240.808H122.123C56.6994 240.808 3.45695 187.562 3.45695 122.122C3.45695 56.7031 56.6994 3.45697 122.124 3.45697C187.566 3.45697 240.808 56.7031 240.808 122.122V240.808Z"
                    fill="#FFFFFF"
                  />
                </svg>
              </button>
            </div>
          </footer>
        </DashboardContext.Provider>
      </ConfigProvider>
    </WebSocketUserProvider>
  );
}

export default Dashboard;
